<div class="card"><div class="card-header d-flex justify-content-between"><h5 class="mb-0">Audit Aktivitas Penting</h5><a id="export" class="btn btn-success">Ekspor</a></div><div class="card-body"><div class="row g-2 align-items-end mb-2"><div class="col-md-2"><input id="awal" class="form-control tanggal-picker" placeholder="Tanggal awal" autocomplete="off"></div><div class="col-md-2"><input id="akhir" class="form-control tanggal-picker" placeholder="Tanggal akhir" autocomplete="off"></div><div class="col-md-2"><input id="user" class="form-control" placeholder="Pengguna"></div><div class="col-md-3"><select id="aksi" class="form-select"><option value="">Semua Aktivitas</option><option>Tambah</option><option>Ubah</option><option>Batal</option><option>Cetak</option><option>Kirim</option><option>Import</option><option>Export</option></select></div><div class="col-md-3"><select id="modul" class="form-select"><option value="">Semua Menu</option><option>Master Data</option><option>Kesiswaan</option><option>Tagihan</option><option>Transaksi</option><option>Tunggakan</option><option>Laporan</option><option>Pengaturan</option></select></div></div><div class="row g-2 align-items-end mb-3"><div class="col-md-10"><input id="q" class="form-control" placeholder="Kata kunci / referensi"></div><div class="col-md-2 d-grid"><button id="cari" class="btn btn-primary"><i class="ti ti-search me-1"></i>Cari</button></div></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aktivitas</th><th>Menu</th><th>Referensi</th><th>Ringkasan</th><th>Aksi</th></tr></thead><tbody id="data"><tr><td colspan="7" class="empty-state">Memuat...</td></tr></tbody></table></div></div></div>
<div class="modal fade" id="modal"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Detail Log</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="detail"></div></div></div></div>
<script>$(function(){flatpickr('.tanggal-picker',{dateFormat:'d-m-Y',allowInput:true,disableMobile:true});function p(){return {awal:$('#awal').val(),akhir:$('#akhir').val(),user:$('#user').val(),aksi:$('#aksi').val(),modul:$('#modul').val(),q:$('#q').val()}}function load(){$.post('<?= base_url('log_aktivitas/result') ?>',p(),r=>$('#data').html(r.length?r.map(x=>`<tr><td>${escapeHtml(x.tanggal)}<br><small>${escapeHtml(x.waktu)}</small></td><td>${escapeHtml(x.nama_user)}</td><td><strong>${escapeHtml(x.jenis_aktivitas)}</strong><br><small>${escapeHtml(x.aksi)}</small></td><td>${escapeHtml(x.modul)}</td><td>${escapeHtml(x.nomor_referensi||'-')}</td><td>${escapeHtml(x.keterangan||'')}</td><td><button class="btn btn-sm btn-primary detail" data-id="${x.id}">Detail</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">Tidak ada log.</td></tr>'),'json').fail(ajaxError)}$('#cari').click(load);$('#export').click(function(){this.href='<?= base_url('log_aktivitas/export') ?>?'+new URLSearchParams(p()).toString()});$(document).on('click','.detail',function(){$.post('<?= base_url('log_aktivitas/detail') ?>',{id:$(this).data('id')},x=>{let pretty=v=>{try{return '<pre class="bg-light p-3 rounded">'+escapeHtml(JSON.stringify(JSON.parse(v),null,2))+'</pre>'}catch(e){return '<pre>'+escapeHtml(v||'-')+'</pre>'}};$('#detail').html(`<div class="row"><div class="col-md-6"><strong>${escapeHtml(x.jenis_aktivitas)}</strong><br>${escapeHtml(x.tanggal+' '+x.waktu)}<br>Pengguna: ${escapeHtml(x.nama_user)}<br>IP: ${escapeHtml(x.ip_address||'-')}</div><div class="col-md-6">Modul: ${escapeHtml(x.modul)}<br>Aksi: ${escapeHtml(x.aksi)}<br>Referensi: ${escapeHtml(x.nomor_referensi||'-')}</div></div><hr><p>${escapeHtml(x.keterangan||'')}</p><h6>Data Sebelum</h6>${pretty(x.data_sebelum)}<h6>Data Sesudah</h6>${pretty(x.data_sesudah)}<h6>Perangkat</h6><small>${escapeHtml(x.user_agent||'-')}</small>`);bootstrap.Modal.getOrCreateInstance(document.getElementById('modal')).show()},'json')});load()});</script>
